   507                                      bool aReceive)
   508  {
   509      otError error = OT_ERROR_NONE;
   510      ExtensionHeader extHeader;
   511
   512      while (aReceive == true || aNextHeader == kProtoHopOpts)
   513      {
   514          VerifyOrExit(aMessage.Read(aMessage.GetOffset(), sizeof(extHeader), &extHeader) == sizeof(extHeader),
   515                       error = OT_ERROR_DROP);
   516
   517          switch (aNextHeader)
   518          {
   519          case kProtoHopOpts:
   520              SuccessOrExit(error = HandleOptions(aMessage, aHeader, aForward));
   521              break;
